import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    if n == 3:
        if a[0] == a[1] == a[2]:
            print("YES")
            print(0)
        else:
            print("NO")
        return

    xor_all = 0
    for num in a:
        xor_all ^= num

    if xor_all == 0:
        print("YES")
        print(0)
        return

    if n % 2 == 1:
        print("NO")
        return

    target = a[0]
    possible = True
    for num in a[1:]:
        if (num ^ target) != (xor_all ^ target):
            possible = False
            break

    if not possible:
        print("NO")
        return

    print("YES")
    print(n // 2)
    for i in range(0, n, 2):
        print(i+1, i+2, 1)

solve()
